const {ML, NDArray} = require('@tensorflow/tfjs-node')
const tf = require('@tensorflow/tfjs');
const fs = require('fs');

// Create a model to predict the price of a given stock in an investing portfolio
const model = ML.sequential();
model.add(ML.layers.dense({inputShape: [1], units: 1, activation: 'relu'}));
model.add(ML.layers.dense({units: 10, activation: 'relu'}));
model.add(ML.layers.dense({units: 1, activation: 'sigmoid'}));
model.compile({loss: 'meanSquaredError', optimizer: 'sgd'});

// Load training data
const trainingData = fs.readFileSync('stock_prices.csv').toString().split('\n');
let features = [];
let labels = [];
for (let row of trainingData) {
  const values = row.split(',');
  const feature = parseFloat(values[0]);
  const label = parseFloat(values[1]); 
  features.push([feature]);
  labels.push([label]);
}
// Convert data to tensors
const featureTensor = new NDArray(features);
const labelTensor = new NDArray(labels);

// Train model
model.fit(featureTensor, labelTensor, {epochs: 50, batchSize: 10})

// Evaluate Model
const testData = fs.readFileSync('test_stock_prices.csv').toString().split('\n');
let testFeatures = [];
let testLabels = [];
for (let row of testData) {
  const values = row.split(',');
  const feature = parseFloat(values[0]);
  const label = parseFloat(values[1]); 
  testFeatures.push([feature]);
  testLabels.push([label]);
}

// Convert data to tensors
const testFeatureTensor = new NDArray(testFeatures);
const testLabelTensor = new NDArray(testLabels);

// Test the model
const result = model.evaluate(testFeatureTensor, testLabelTensor)

// Print the result
console.log('Result: ', result);
